import{_ as o,l,o as e,c as n,v as r,p as s,x as t,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"计数器","description":"","frontmatter":{"title":"计数器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/counter-circuit.md","filePath":"cs/counter-circuit.md","lastUpdated":1789023840000}'),h={name:"cs/counter-circuit.md"};function u(_,a,E,m,A,f){const i=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="计数器" tabindex="-1">计数器 <a class="header-anchor" href="#计数器" aria-label="Permalink to &quot;计数器&quot;">​</a></h1><div class="epigraph"><p>计数器是沿固定环行走的状态机；二进制加一与独热转圈是两种编码，进位链决定延迟。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/moore-mealy">Moore 与 Mealy</a>钉死了现态寄存器加下一态逻辑。本课不重讲 Moore/Mealy，也不从操作系统时间片另起。缺口是：最常用的一种 FSM 值得单独成块——<strong>计数器</strong>：状态是整数，下一态是加一（或减一），绕模 \\(2^n\\) 或任意模。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>通用 FSM 真值表对 \\(2^n\\) 个计数状态太笨。缺口是结构：寄存器接加法器（或增量器），使能接「是否计数」，同步复位。模 \\(M\\) 不是 2 的幂时，比较到 \\(M-1\\) 再回 0。延迟：增量器的进位与<a href="/cs/adder-cla">加法器</a>同类，高速计数要用超前或简单的 toggling 结构（Johnson、线性反馈另说）。</p><p>程序计数器是加载型计数器：通常 +4，也能被跳转 MUX 加载——后课数据通路会用，本课先给 +1 模板。</p><h3 id="异步进位计数器不是同步设计默认" tabindex="-1">异步进位计数器不是同步设计默认 <a class="header-anchor" href="#异步进位计数器不是同步设计默认" aria-label="Permalink to &quot;异步进位计数器不是同步设计默认&quot;">​</a></h3><p>行波计数器把低位 Q 当高位时钟，省组合，但各比特翻转时刻不同，译码会毛刺，也不满足单时钟建立保持模型。主干用同步计数：全体 FF 同一时钟。</p><p><span class="marginnote">Harris 区分异步与同步计数器，推荐同步。后课 DRAM 刷新计数、定时器都是本课块。PC+4 的 4 是字节编址步长，加法器仍是本课增量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>同步二进制：\\(D=Q+1\\) 当 en，否则 \\(D=Q\\)。模 \\(M\\)：下一态组合在 \\(Q=M-1\\) 时出 0。独热计数：移位环，译码免费，状态数等于 FF 数。</p>',11)),(e(),s(p,null,{default:t(()=>[c(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20REG%5B%22%E7%8A%B6%E6%80%81%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%20--%3E%20INC%5B%22%E5%A2%9E%E9%87%8F%20%2F%20%E6%A8%A1%20M%22%5D%0A%20%20INC%20--%3E%20REG%0A%20%20REG%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%AD%98%E5%82%A8%E5%99%A8%E9%98%B5%E5%88%97%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>定时、分频、寻址扫描（用计数输出当译码器输入）都是本课。与 FSM 的关系：计数器是状态图上的一条圈；需要分支（暂停、加载、上下数）时回到带 MUX 的寄存器，仍是 FSM。</p><p>时序：增量组合的 \\(t_{pd}\\) 必须满足到下一拍 D 的建立。宽计数器关键路径在进位。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲原子钟、不把 NTP 请进来。LFSR 伪随机是线性反馈移位，不是 +1，后课需要散列时再出现。不把超标量多 PC 提前。</p><p>后课默认：计步、刷新、PC+4 都是同步计数/加载寄存器；不用异步行波当系统时钟树。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>计数器是下一态为加一的 FSM，用增量器实现。</li><li>同步全体共时钟；异步行波不进主干。</li><li>模非 2 幂靠检测回零；PC 是可加载的计数器。</li><li>出处：Harris and Harris。</li></ul>',8))])}const T=o(h,[["render",u]]);export{P as __pageData,T as default};
